 3→import { useState, useEffect, useCallback } from "react";
 4→import styles from "./IntroAnimation.module.css";
 5→
 6→const SESSION_KEY = "jaime-intro-played";
 7→
 8→// Timeline (ms)
 9→const T_NAME = 600;
10→const T_FADE = 2400;
11→const T_CLEANUP = 3100;
12→
13→export function IntroAnimation() {
14→  const [phase, setPhase] = useState<
15→    "check" | "playing" | "fadeOut" | "done"
16→  >("check");
17→  const [nameVisible, setNameVisible] = useState(false);
18→
19→  const skipIntro = useCallback(() => {
20→    setPhase("done");
21→    try {
22→      sessionStorage.setItem(SESSION_KEY, "1");
23→    } catch {
24→      // sessionStorage unavailable
25→    }
26→  }, []);
27→
28→  useEffect(() => {
29→    // Check if already played this session
30→    try {
31→      if (sessionStorage.getItem(SESSION_KEY)) {
32→        setPhase("done");
33→        return;
34→      }
35→    } catch {
36→      // sessionStorage unavailable, play anyway
37→    }
38→
39→    // Check reduced motion preference
40→    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
41→      skipIntro();
42→      return;
43→    }
44→
45→    setPhase("playing");
46→
47→    // Name reveals
48→    const t1 = setTimeout(() => setNameVisible(true), T_NAME);
49→    // Fade out overlay
50→    const t2 = setTimeout(() => setPhase("fadeOut"), T_FADE);
51→    // Remove from DOM
52→    const t3 = setTimeout(() => {
53→      setPhase("done");
54→      try {
55→        sessionStorage.setItem(SESSION_KEY, "1");
56→      } catch {
57→        // sessionStorage unavailable
58→      }
59→    }, T_CLEANUP);
60→
61→    return () => {
62→      clearTimeout(t1);
63→      clearTimeout(t2);
64→      clearTimeout(t3);
65→    };
66→  }, [skipIntro]);
67→
68→  if (phase === "done") return null;
69→
70→  return (
71→    <div
72→      className={`${styles.overlay} ${phase === "fadeOut" ? styles.fadeOut : ""}`}
73→      aria-hidden="true"
74→    >
75→      <div className={styles.content}>
76→        <div className={styles.nameMask}>
77→          <span
78→            className={`${styles.name} ${nameVisible ? styles.nameVisible : ""}`}
79→          >
80→            Jaime Ibrahim
81→            <span className={styles.separator}>|</span>
82→            Brand Design Director
83→          </span>
84→        </div>
85→      </div>
86→    </div>
87→  );
88→}
