 1→/* --- Intro Animation Overlay --- */
 2→.overlay {
 3→  position: fixed;
 4→  inset: 0;
 5→  z-index: 9999;
 6→  background: var(--bg);
 7→  display: flex;
 8→  align-items: center;
 9→  justify-content: center;
10→  pointer-events: none;
11→}
12→
13→.overlay.fadeOut {
14→  animation: overlayFade 600ms var(--ease-out) forwards;
15→}
16→
17→.overlay.hidden {
18→  display: none;
19→}
20→
21→/* --- Center text block --- */
22→.content {
23→  position: relative;
24→  z-index: 1;
25→  text-align: center;
26→  display: flex;
27→  align-items: center;
28→  justify-content: center;
29→}
30→
31→/* --- Name --- */
32→.nameMask {
