57→}
58→
59→/* --- Keyframes --- */
60→@keyframes textReveal {
61→  from { transform: translateY(110%); }
62→  to { transform: translateY(0); }
63→}
64→
65→@keyframes overlayFade {
66→  from { opacity: 1; }
67→  to { opacity: 0; }
68→}
69→
70→/* --- Reduced motion --- */
71→@media (prefers-reduced-motion: reduce) {
72→  .name.nameVisible {
73→    animation: none;
74→    transform: translateY(0);
75→  }
76→  .overlay.fadeOut {
77→    animation: none;
78→    opacity: 0;
79→  }
80→}
